import json, os, collections, datetime
D='/tmp/export'
def load(t):
    return [json.loads(l) for l in open(os.path.join(D,t+'.ndjson'))]
TYPES=['AllergyIntolerance','Basic','Condition','DocumentReference','EpisodeOfCare','MedicationAdministration','MedicationDispense','Observation','Patient','Specimen','Task']
R={t:load(t) for t in TYPES}
byid={}
for t in TYPES:
    for r in R[t]:
        byid[r['id']]=r
EXT='https://chartr.example/fhir/StructureDefinition/'
def ext(r,name,*keys):
    for e in r.get('extension',[]):
        if e['url']==EXT+name:
            for k in ('valueDateTime','valueString','valueDate','valueCode'):
                if k in e: return e[k]
    return None
def et(r): return ext(r,'event-time')
def subj(r):
    s=r.get('subject') or r.get('patient') or r.get('for')
    return s['reference'].split('/')[-1] if s else None
pats={p['id']:p for p in R['Patient']}
eps=collections.defaultdict(list)
for e in R['EpisodeOfCare']: eps[subj(e)].append(e)
chart=collections.defaultdict(list)
for t in TYPES:
    if t in ('Patient','EpisodeOfCare'): continue
    for r in R[t]:
        s=subj(r)
        if s: chart[s].append(r)
for k in chart: chart[k].sort(key=lambda r: et(r) or r.get('authoredOn') or '')
EOF
