        print(f'{tm} {t} {i} {r["code"]["text"]!r} coll={r.get("effectiveDateTime")} issued={r.get("issued")} status={r["status"]} val={r.get("valueString")!r} acc={acc} spec={sp} note={notes}')
    elif t=='Specimen':
        print(f'{tm} {t} {i} acc={r.get("accessionIdentifier",{}).get("value")} coll={r.get("collection",{}).get("collectedDateTime")} by={r.get("collection",{}).get("collector",{}).get("display")} label={ext(r,"label-name")}/{ext(r,"label-mrn")}/{ext(r,"label-dob")} type={r.get("type",{}).get("text")}')
    elif t=='MedicationAdministration':
        print(f'{tm} {t} {i} {r["medicationCodeableConcept"]["text"]} status={r["status"]} eff={r.get("effectiveDateTime")} dose={r.get("dosage",{}).get("text")} note={" | ".join(n["text"] for n in r.get("note",[]))}')
    elif t=='MedicationDispense':
        print(f'{tm} {t} {i} {r["medicationCodeableConcept"]["text"]} status={r["status"]} qty={r.get("quantity",{}).get("value")} days={r.get("daysSupply",{}).get("value")} when={r.get("whenHandedOver")} sig={r.get("dosageInstruction",[{}])[0].get("text")} note={" | ".join(n["text"] for n in r.get("note",[]))}')
    elif t=='DocumentReference':
        print(f'{tm} {t} {i} type={r["type"]["text"]} author={r.get("author",[{}])[0].get("display")} role={ext(r,"author-role")} date={r.get("date")}')
        print('    '+r['description'].replace('\n','\n    '))
    elif t=='AllergyIntolerance':
        print(f'{tm} {t} {i} {r["code"]["text"]} rx={r.get("reaction",[{}])[0].get("manifestation",[{}])[0].get("text")}')
    elif t=='Task':
        print(f'{tm} {t} {i} {r["status"]} {r.get("code",{}).get("coding",[{}])[0].get("code")} {r.get("description")}')
# accessioning entries matching this patient's accessions
accs={ext(s,'accession') if False else s.get('accessionIdentifier',{}).get('value') for s in chart[pid] if s['resourceType']=='Specimen'}
print('--- Accessioning entries for accessions in chart ---')
for b in R['Basic']:
    a=ext(b,'accession')
    if a in accs:
        print(f'{et(b)} Basic {b["id"]} acc={a} {ext(b,"patient-name")}/{ext(b,"patient-mrn")}/{ext(b,"patient-dob")} recv={ext(b,"received")} author={b.get("author",{}).get("display")}')
EOF
